<script>
 import {onMount} from 'svelte';
 import {api} from './auth.js';
 export let admin=false;
 let products=[],orders=[],cart={},form=null,photoFile=null,photoPreview='',busy=false,error='',message='',view='products',customerName='',phone='',address='';
 const rupiah=n=>new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(n);
 $: cartItems=products.filter(p=>(cart[p.id]||0)>0);
 $: total=cartItems.reduce((sum,p)=>sum+p.price*cart[p.id],0);
 onMount(load);
 async function load(){try{products=(await api('/catalog')).products;if(admin)orders=(await api('/product-orders')).orders;}catch(e){error=e.message;}}
 function edit(product){form=product?{...product}:{name:'',description:'',price:0,image:''};photoFile=null;photoPreview='';error='';message='';}
 function selectPhoto(event){photoFile=event.currentTarget.files?.[0]||null;photoPreview='';error='';if(!photoFile)return;const reader=new FileReader();reader.onload=()=>{photoPreview=String(reader.result||'');};reader.onerror=()=>{error='Foto tidak dapat dibaca. Coba pilih foto lain.';};reader.readAsDataURL(photoFile);}
 async function compress(file){if(!file.type.startsWith('image/'))throw new Error('Pilih file foto.');const url=URL.createObjectURL(file);try{const picture=new Image();picture.src=url;await picture.decode();let scale=Math.min(1,800/Math.max(picture.naturalWidth,picture.naturalHeight));const canvas=document.createElement('canvas');for(let attempt=0;attempt<5;attempt++){canvas.width=Math.max(1,Math.round(picture.naturalWidth*scale));canvas.height=Math.max(1,Math.round(picture.naturalHeight*scale));canvas.getContext('2d').drawImage(picture,0,0,canvas.width,canvas.height);const image=canvas.toDataURL('image/jpeg',0.72);if(image.length<=400000)return image;scale*=0.75;}throw new Error('Foto terlalu besar. Pilih foto lain.');}finally{URL.revokeObjectURL(url);}}
 async function save(){busy=true;error='';try{if(photoFile)form.image=await compress(photoFile);await api(form.id?'/catalog/'+form.id:'/catalog',{method:form.id?'PATCH':'POST',body:JSON.stringify({...form,price:Number(form.price)})});form=null;await load();message='Produk berhasil disimpan.';}catch(e){error=e.message;}finally{busy=false;}}
 async function remove(product){if(!confirm('Hapus produk “'+product.name+'” dari katalog?'))return;busy=true;try{await api('/catalog/'+product.id,{method:'DELETE',body:JSON.stringify({revision:product.revision})});if(form?.id===product.id){form=null;photoFile=null;photoPreview='';}await load();message='Produk dihapus dari katalog.';}catch(e){error=e.message;}finally{busy=false;}}
 async function checkout(){if(!cartItems.length){error='Keranjang masih kosong.';return;}busy=true;error='';try{await api('/product-orders',{method:'POST',body:JSON.stringify({customer_name:customerName,phone,address,cart:cartItems.map(p=>({id:p.id,quantity:cart[p.id],price:p.price}))})});cart={};customerName='';phone='';address='';view='products';message='Pesanan berhasil dikirim. Admin akan menghubungi Anda untuk ongkir dan pembayaran.';}catch(e){error=e.message;}finally{busy=false;}}
</script>
<div class="toolbar">{#if admin}<button class="primary" onclick={()=>edit(null)}>+ Tambah Produk</button><button onclick={()=>view=view==='orders'?'products':'orders'}>{view==='orders'?'Katalog':'Pesanan Produk ('+orders.length+')'}</button>{:else}<button class="primary" onclick={()=>view=view==='cart'?'products':'cart'}>{view==='cart'?'Kembali ke katalog':'Keranjang ('+cartItems.length+')'}</button>{/if}</div>
{#if error}<p class="error" role="alert">{error}</p>{/if}{#if message}<p class="message" role="status">{message}</p>{/if}
{#if form&&admin}<section class="card"><h2>{form.id?'Edit Produk':'Tambah Produk'}</h2><form onsubmit={e=>{e.preventDefault();save();}}><label>Nama produk<input required maxlength="120" bind:value={form.name}/></label><label>Deskripsi<textarea maxlength="3000" rows="4" bind:value={form.description}></textarea></label><label>Harga (Rp)<input type="number" required min="0" max="2147483647" step="1" bind:value={form.price}/></label><span class="photo-title">Foto produk</span><label class="photo-picker" for="product-photo"><span>📷 Pilih Foto dari Galeri</span><input id="product-photo" type="file" accept="image/*" onchange={selectPhoto}/></label>{#if photoFile}<p>Foto dipilih: {photoFile.name}</p>{/if}{#if photoPreview || form.image}<img class="preview" src={photoPreview || form.image} alt="Pratinjau foto produk"/>{/if}<div class="toolbar"><button class="primary" disabled={busy}>{busy?'Menyimpan…':'Simpan Produk'}</button><button type="button" onclick={()=>form=null}>Batal</button></div></form></section>{/if}
{#if view==='orders'&&admin}<h2>Pesanan Produk</h2>{#each orders as order}<section class="card"><strong>{order.customer_name}</strong><p>{order.phone}<br/>{order.address}</p>{#each order.items as item}<p>{item.name} · {item.quantity} × {rupiah(item.price)}</p>{/each}<strong>Total produk: {rupiah(order.total)}</strong><p>Menunggu konfirmasi · {new Date(order.created_at).toLocaleString('id-ID',{timeZone:'Asia/Jakarta'})} WIB</p></section>{:else}<p>Belum ada pesanan produk.</p>{/each}
{:else if view==='cart'&&!admin}<section class="card"><h2>Keranjang</h2>{#each cartItems as product}<div class="cart-row"><span>{product.name} · {rupiah(product.price)}</span><input aria-label={'Jumlah '+product.name} type="number" min="0" max="100" bind:value={cart[product.id]}/></div>{:else}<p>Keranjang masih kosong.</p>{/each}<strong>Total produk: {rupiah(total)}</strong><p>Ongkir dan pembayaran dikonfirmasi oleh Admin.</p><form onsubmit={e=>{e.preventDefault();checkout();}}><label>Nama penerima<input required maxlength="100" bind:value={customerName}/></label><label>Nomor WhatsApp<input required type="tel" maxlength="25" bind:value={phone}/></label><label>Alamat pengiriman<textarea required maxlength="500" rows="3" bind:value={address}></textarea></label><button class="primary" disabled={busy||!cartItems.length}>{busy?'Mengirim…':'Checkout'}</button></form></section>
{:else}<div class="grid">{#each products as product}<section class="card">{#if product.image}<img src={product.image} alt={product.name}/>{/if}<h2>{product.name}</h2><p class="description">{product.description}</p><strong>{rupiah(product.price)}</strong><div class="toolbar">{#if admin}<button onclick={()=>edit(product)}>Edit</button><button onclick={()=>remove(product)} disabled={busy}>Hapus</button>{:else}<button class="primary" onclick={()=>{cart={...cart,[product.id]:Math.min(100,(cart[product.id]||0)+1)};message='Ditambahkan ke keranjang.';}}>+ Keranjang</button>{/if}</div></section>{:else}<p>Belum ada produk di katalog.</p>{/each}</div>{/if}
<style>
 .photo-title{font-weight:700}.photo-picker{position:relative;display:flex;align-items:center;justify-content:center;min-height:58px;padding:12px;border:1px solid #c9a754;border-radius:10px;background:#fffdf8;color:#004b35;text-align:center;cursor:pointer;overflow:hidden}.photo-picker input{position:absolute;inset:0;width:100%;height:100%;margin:0;padding:0;opacity:0;cursor:pointer}.photo-picker:focus-within{outline:3px solid #f5d47b;outline-offset:2px}
 .toolbar{display:flex;gap:10px;flex-wrap:wrap;margin:0 0 20px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:15px}.card{background:#004b35;color:#f5d47b;border:1px solid #c9a754;border-radius:18px;padding:20px;margin-bottom:15px;overflow:hidden}.card img{width:100%;max-height:250px;object-fit:cover;border-radius:10px}.card img.preview{max-width:180px}.card h2{font-size:19px}.card p{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.5}.card strong{display:block}.card .toolbar{margin:16px 0 0}button{font:inherit;border:1px solid #c9a754;border-radius:9px;padding:10px 14px;background:#fffdf8;color:#004b35;font-weight:700;cursor:pointer}button.primary{background:#00543b;color:#f5d47b}button:disabled{opacity:.6}form{display:grid;gap:14px;margin-top:18px}label{display:grid;gap:7px;font-weight:700}input,textarea{font:inherit;width:100%;padding:11px;border-radius:9px;border:1px solid #b9cfba;color:#123c2b;background:white}textarea{resize:vertical}.cart-row{display:flex;justify-content:space-between;gap:10px;padding:10px 0}.cart-row input{width:72px}.error,.message{padding:12px;border-radius:8px}.error{background:#ffede5;color:#8a2c18}.message{background:#eaf2e9;color:#244d32}@media(max-width:500px){.grid{grid-template-columns:1fr 1fr;gap:10px}.card{padding:15px}.card h2{font-size:16px}.card .toolbar button{font-size:12px}}
</style>
